        mov     al, [apply__a]
        cmp     al, 14                      ; byte operands, no widening
        jne     .L890                       ; unsigned ==
; ---- viewGoto( textLines() - 1, 0 )
        call    textLines
        mov     ax, [textLines__ret]
        dec     ax
        push    ax                          ; argument evaluated before any is stored
        mov     word [viewGoto__col], 0
        pop     ax
        mov     [viewGoto__ln], ax
        call    viewGoto
        jmp     .L891
.L890:
