        mov     al, [apply__a]
        cmp     al, 18                      ; byte operands, no widening
        jne     .L896                       ; unsigned ==
; ---- fieldClear()
        call    fieldClear
; ---- prompting = true
        mov     byte [prompting], 1
; ---- message = 0
        mov     word [message], 0
; ---- onMatch = false
        mov     byte [onMatch], 0
        jmp     .L897
.L896:
